// ABOUTME: Runs the emitter's golden .mirroir/ tree through the built mirroir-run binary as a sample.
// ABOUTME: Every declared flow reaches a stub mirroir-mcp as one ios block, step for step, and the sample passes.

//! Emitter → runner seam, end to end through the binary. The tree under
//! `tests/fixtures/emitted/` is byte-exact `generate_skill emit=true` output
//! (regenerated by the Swift `EmittedScenarioContractTests`); the parse, plan
//! and render checks on it live in `src/emitted_scenario_contract.rs`. Here a
//! stub `mirroir-mcp` named by `MIRROIR_MCP_BIN` stands in for the phone, so
//! the case is macOS-only: elsewhere the block is refused by host.

#![cfg(target_os = "macos")]

mod common;

use std::fs;

use common::{Sandbox, repo_path};

/// The emitted Clock app dir, as `mirroir.yaml`'s `local:` entry names it.
const CLOCK_SAMPLE: &str = "tests/fixtures/emitted/.mirroir/apps/clock";

/// A `mirroir-mcp test` that keeps the block it was handed and reports a pass:
/// argv is `test --report-json <report> --capture ios <block>`.
const PASSING_MIRROIR_MCP: &str = concat!(
    "#!/bin/sh\n",
    "PATH=/bin:/usr/bin\n",
    "export PATH\n",
    "cp \"$6\" \"$(basename \"$(dirname \"$6\")\").handed.yaml\"\n",
    "cat \"$MIRROIR_TEST_REPORT\" > \"$3\"\n",
);

/// Every emitted flow runs as a must-pass scenario, each handing mirroir-mcp
/// a block with every emitted step — the own-app reset, the taps, their
/// arrival waits and a scrolled-to row included — and the sample's verdict
/// is a pass.
#[test]
fn the_emitted_sample_hands_every_step_of_every_flow_to_mirroir_mcp() -> Result<(), String> {
    let sandbox = Sandbox::new()?;
    let stub = sandbox.stub_bin("mirroir-mcp", PASSING_MIRROIR_MCP)?;
    let report = repo_path("src/target/fixtures/mirroir-mcp-report.json");
    let sample = repo_path(CLOCK_SAMPLE);

    let run = sandbox.run_with_env(
        &["--sample", &sample],
        &[("MIRROIR_MCP_BIN", &stub), ("MIRROIR_TEST_REPORT", &report)],
    )?;
    if run.is_failure() {
        return Err(format!("the emitted sample failed\n{}", run.output()));
    }

    for flow in ["add-alarm", "gym-alarm", "world-clock"] {
        let scenario = fs::read_to_string(repo_path(&format!(
            "{CLOCK_SAMPLE}/scenarios/{flow}.ios.yaml"
        )))
        .map_err(|e| format!("read {flow}: {e}"))?;
        let handed = find_handed(&sandbox, flow)?;
        let emitted_steps = scenario.lines().filter(|l| l.starts_with("  - ")).count();
        let handed_steps = handed.lines().filter(|l| l.starts_with("  - ")).count();
        if handed_steps != emitted_steps {
            return Err(format!(
                "{flow}: mirroir-mcp got {handed_steps} of {emitted_steps} steps\n{handed}"
            ));
        }
    }
    let add_alarm = find_handed(&sandbox, "add-alarm")?;
    for line in [
        "  - reset_app: \"Clock\"\n  - launch: \"Clock\"\n",
        "  - tap: \"Add Alarm\"\n  - wait_for: \"Cancel\"\n",
        "  - tap: \"Cancel\"\n",
    ] {
        if !add_alarm.contains(line) {
            return Err(format!("the add-alarm block lacks `{line}`\n{add_alarm}"));
        }
    }
    let gym_alarm = find_handed(&sandbox, "gym-alarm")?;
    let scrolled_tap = "  - scroll_to: \"Gym\"\n  - tap: \"Gym\"\n";
    if !gym_alarm.contains(scrolled_tap) {
        return Err(format!(
            "the gym-alarm block lacks `{scrolled_tap}`\n{gym_alarm}"
        ));
    }
    Ok(())
}

/// The block the stub kept for `flow`: it names its copy after the
/// per-scenario workspace directory, which carries the scenario's name.
fn find_handed(sandbox: &Sandbox, flow: &str) -> Result<String, String> {
    let mut stack = vec![sandbox.path().to_path_buf()];
    while let Some(dir) = stack.pop() {
        let entries = fs::read_dir(&dir).map_err(|e| format!("read {}: {e}", dir.display()))?;
        for entry in entries {
            let path = entry.map_err(|e| e.to_string())?.path();
            let name = path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or_default();
            if path.is_dir() {
                stack.push(path.clone());
            } else if name.ends_with(".handed.yaml") && name.contains(flow) {
                return fs::read_to_string(&path).map_err(|e| e.to_string());
            }
        }
    }
    Err(format!("mirroir-mcp was never handed the {flow} block"))
}
